import numpy as np
from scipy.stats import planck
import json
import os

def gen(x, lam, name):
    """
    Generate fixture data and write to file.

    Parameters
    ----------
    x : ndarray
        Input values.
    lambda : ndarray
        Shape parameter.
    name : str
        Output filename.

    Examples
    --------
    >>> x = np.random.rand(1000) * 10
    >>> lam = np.random.rand(1000)
    >>> gen(x, lam, "data.json")
    """
    # Compute PDF values:
    z = np.array([planck.pmf(int(xi), pi) for xi, pi in zip(x, lam)])

    # Store data to be written to file as a dictionary:
    data = {
        "x": x.tolist(),
        "lambda": lam.tolist(),
        "expected": z.tolist()
    }

    # Based on the script directory, create an output filepath:
    filepath = os.path.join(dir_path, name)

    # Write the data to the output filepath as JSON:
    with open(filepath, "w") as outfile:
        json.dump(data, outfile, indent=4)
    
    # Include trailing newline
    with open(filepath, "a") as outfile:
        outfile.write("\n")

# Get the directory in which this file resides:
dir_path = os.path.dirname(os.path.abspath(__file__))

# Large success probability:
x = np.round(np.random.rand(1000) * 10.0)
lam = (np.random.rand(1000) * 10) + 10
gen(x, lam, "large_lambda.json")

# Small success probability:
x = np.round(np.random.rand(1000) * 10.0)
lam = np.random.rand(1000) * 0.5
gen(x, lam, "small_lambda.json")
